"""static bool send_up(coll_t *c, int r) {
    uint8_t frame[MAX_FRAME];
    const uint8_t swmac[6] = {2, 1, 0, 0, 0, (uint8_t)(r + 1)};
    const uint8_t hstmac[6] = {2, 0, 0, 0, 0, (uint8_t)(r + 1)};
    uint32_t swip = htonl(0x0a000065u + (uint32_t)r);
