    const uint8_t swmac[6] = {2, 1, 0, 0, 0, (uint8_t)(d + 1)};
    const uint8_t hstmac[6] = {2, 0, 0, 0, 0, (uint8_t)(d + 1)};
    uint32_t swip = htonl(0x0a000065u + (uint32_t)d);
